```javascript
import * as THREE from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Geometry constants
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const PADDING = 0.375;
  const DISC_DIAM = 0.4;
  const DISC_DEPTH = 0.05;
  const TOTAL_W = CARD_W * 3 + GAP * 2;
  const START_X = -TOTAL_W / 2 + CARD_W / 2;

  // Colors
  const COL_ACCENT = new THREE.Color('#ff2a38');
  const COL_PAPER = new THREE.Color('#e8ecf2');
  const COL_GRAD_TOP = new THREE.Color('#191921');
  const COL_GRAD_BOT = new THREE.Color('#121218');

  const CARD_DATA = [
    {
      glyph: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      glyph: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      glyph: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  function createCardMaterial() {
    const material = new THREE.MeshStandardNodeMaterial({
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      fog: false
    });

    // TSL gradient node
    const colorA = vec3(COL_GRAD_TOP.r, COL_GRAD_TOP.g, COL_GRAD_TOP.b);
    const colorB = vec3(COL_GRAD_BOT.r, COL_GRAD_BOT.g, COL_GRAD_BOT.b);
    material.colorNode = mix(colorA, colorB, uv().y);

    material.opacity = 0;
    return material;
  }

  function createIconDisc() {
    const geometry = new THREE.CylinderGeometry(
      DISC_DIAM / 2,
      DISC_DIAM / 2,
      DISC_DEPTH,
      32
    );

    const material = new THREE.MeshStandardNodeMaterial({
      color: 0x2a2a30,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      emissive: COL_ACCENT,
      emissiveIntensity: 1.6,
      fog: false
    });

    const disc = new THREE.Mesh(geometry, material);
    disc.rotation.x = Math.PI / 2;
    return disc;
  }

  const timelines = [];
  const cardGroups = [];

  CARD_DATA.forEach((data, index) => {
    const group = new THREE.Group();
    group.position.x = START_X + index * (CARD_W + GAP);
    group.position.y = 0.2;

    // Card background plane
    const cardGeom = new THREE.PlaneGeometry(CARD_W, CARD_H);
    const cardMat = createCardMaterial();
    const cardPlane = new THREE.Mesh(cardGeom, cardMat);
    group.add(cardPlane);

    // Icon seat disc
    const disc = createIconDisc();
    const discY = CARD_H / 2 - PADDING - DISC_DIAM / 2;
    disc.position.y = discY;
    group.add(disc);

    // Glyph text (on disc)
    const glyphMesh = ctx.fontAtlas.create({
      text: data.glyph,
      fontSize: 20,
      fontWeight: 700,
      color: '#ff2a38'
    });
    glyphMesh.position.set(0, discY, 0.05);
    group.add(glyphMesh);

    // Title text
    const titleMesh = ctx.fontAtlas.create({
      text: data.title,
      fontSize: 20,
      fontWeight: 600,
      color: '#e8ecf2',
      align: 'center',
      maxWidth: CARD_W - 2 * PADDING
    });
    titleMesh.position.set(0, discY - DISC_DIAM / 2 - 0.25, 0.01);
    group.add(titleMesh);

    // Body text
    const bodyMesh = ctx.fontAtlas.create({
      text: data.body,
      fontSize: 13,
      fontWeight: 400,
      color: '#e8ecf2',
      align: 'center',
      maxWidth: CARD_W - 2 * PADDING
    });
    bodyMesh.position.set(0, discY - DISC_DIAM / 2 - 0.5, 0.01);
    group.add(bodyMesh);

    // Hover interaction handler
    group.userData.handlers = {
      hover: (event) => {
        if (event.isHovering) {
          gsap.to(group.position, {
            y: 0.06,
            z: 0.12,
            duration: 0.18,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
          gsap.to(disc.material, {
            emissiveIntensity: 2.2,
            duration: 0.18
          });
        } else {
          gsap.to(group.position, {
            y: 0,
            z: 0,
            duration: 0.18,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          });
          gsap.to(disc.material, {
            emissiveIntensity: 1.6,
            duration: 0.18
          });
        }
      }
    };

    cardGroups.push(group);
    root.add(group);
  });

  // Mount animation: stagger-cards with fade-up
  const mountTimeline = gsap.timeline();

  cardGroups.forEach((card, index) => {
    // Position animation
    mountTimeline.to(
      card.position,
      {
        y: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      index * 0.08
    );

    // Opacity animation on card plane
    card.traverse((child) => {
      if (child.material && child.material.opacity !== undefined) {
        mountTimeline.to(
          child.material,
          {
            opacity: 1,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          },
          index * 0.08
        );
      }
    });
  });

  timelines.push(mountTimeline);

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());

    root.traverse((node) => {
      if (node.geometry) {
        node.geometry.dispose();
      }
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((m) => m.dispose());
        } else {
          node.material.dispose();
        }
      }
    });
  };

  return root;
}
